import { $ } from '@wdio/globals';
import BaseScreen from '@screenobjects/commons/base.screen.ts';
import LocatorProvider from '@common/locators/locator-provider.js';
import { TypeLocator } from '@common/enums/locator-type.enum.js';
import Locators from '@locators/payment/verify-sales-message.locator.json' with { type: 'json' };
import { getTimeoutFromEnv } from '@common/utils/env/environment-config.js';

const timeout: number = getTimeoutFromEnv();

class VerifySalesMessageScreen extends BaseScreen {

    public get salesButton() {
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, Locators["verifySalesMessageIos"].salesButton,
            TypeLocator.ANDROID, Locators["verifySalesMessageAndroid"].salesButton
        );
        return $(locator);
    }

    public get noSalesMessage() {
        const locator = LocatorProvider.getElement(
            TypeLocator.XPATH, Locators["verifySalesMessageIos"].noSalesMessage,
            TypeLocator.ANDROID, Locators["verifySalesMessageAndroid"].noSalesMessage
        );
        return $(locator);
    }

    public async userPoderAccederSales(): Promise<void> {
        await this.uiHelper.waitForElementExistByLocator(this.salesButton, true);
        await this.salesButton.click();
    }

    public async verifyNoSalesMessage(): Promise<void> {
        await this.uiHelper.waitForElementDisplayedAndExpect(this.noSalesMessage, timeout, 'The expected element was not displayed');
    }
}

export default new VerifySalesMessageScreen();

{
    "verifySalesMessageAndroid": {
        "salesButton": "new UiSelector().text(\"Ver ventas\")",
        "noSalesMessage": "new UiSelector().text(\"Aún no hay ninguna venta.\")"
    },
    "verifySalesMessageIos": {
        "salesButton": "",
        "noSalesMessage": ""
    }
}
